# ============================================================# NUMERICAL SIMULATIONS# Moral Hazard, Governance, and Regime Selection# ============================================================import numpy as npimport matplotlib.pyplot as pltimport osfrom matplotlib.colors import TwoSlopeNormimport pandas as pd# ============================================================# OUTPUT DIRECTORY# ============================================================OUTPUT_DIR = "output"os.makedirs(OUTPUT_DIR, exist_ok=True)plt.rcParams.update({    "font.family": "serif",    "font.size": 11,    "axes.labelsize": 12,    "axes.titlesize": 12,    "legend.fontsize": 10,    "xtick.labelsize": 10,    "ytick.labelsize": 10,    "figure.dpi": 150,    "savefig.dpi": 300,    "axes.linewidth": 0.8,    "lines.linewidth": 1.4,    "grid.linewidth": 0.4,    "grid.alpha": 0.25,    "legend.frameon": False})# ============================================================# PARAMETERS# ============================================================B = 0.5K0 = 3.0c = 1.0d = 1.0gamma = 0.8epsbar = 1.5alpha_baseline = 0.5beta_baseline = 0.5s_bar = min(1.0, gamma / d)kappa = gamma * c / (d * epsbar)# ============================================================# MODEL FUNCTIONS# ============================================================def A(mu):    """Total benefit from compliance."""    return B + K0 * (1.0 - mu)def eps_star(s, mu):    """Critical cost threshold."""    if s <= 0.0:        return np.inf    return (A(mu) - 0.5 * c * s**2) / sdef pi_func(s, mu):    """Expected compliance probability."""    es = eps_star(s, mu)    if es >= epsbar:        return 1.0    elif es <= 0.0:        return 0.0    else:        return es / epsbardef s1_frontier(mu):    """Lower frontier: below s1, pi = 1."""    return (-epsbar + np.sqrt(epsbar**2 + 2.0 * c * A(mu))) / cdef s0_frontier(mu):    """Upper frontier: above s0, pi = 0."""    return np.sqrt(2.0 * A(mu) / c)def mu_G_star():    """Critical implicit-protection threshold."""    return 1.0 - (epsbar * s_bar + 0.5 * c * s_bar**2 - B) / K0def fixed_point_internal(mu):    """Internal fixed point E_I(mu) = (s*, p*)."""    denom = epsbar * d / gamma + 0.5 * c    s_fp = np.sqrt(A(mu) / denom)    p_fp = (d / gamma) * s_fp    return s_fp, p_fpdef best_reply_core(p):    """Core-country best reply."""    return min(1.0, (gamma / d) * p)def system_step(s, p, mu, alpha, beta):    """One-step iteration of the dynamic system."""    s_next = (1.0 - alpha) * s + alpha * best_reply_core(p)    p_next = (1.0 - beta) * p + beta * pi_func(s, mu)    return s_next, p_nextdef simulate(s0, p0, mu, alpha, beta, T=300):    """Simulate the system for T periods."""    s_path = np.zeros(T + 1)    p_path = np.zeros(T + 1)    s_path[0], p_path[0] = s0, p0    for t in range(T):        s_path[t + 1], p_path[t + 1] = system_step(            s_path[t], p_path[t], mu, alpha, beta        )    return s_path, p_pathdef jacobian_determinant(alpha, beta, kappa):    """Determinant of the Jacobian at the internal fixed point."""    return (1.0 - alpha) * (1.0 - beta) + alpha * beta * (1.0 + kappa)def alpha_critical_symmetric(kappa):    """Critical threshold under alpha = beta."""    return 2.0 / (2.0 + kappa)def classify_regime(mu, tol=1e-10):    """Classify regime relative to mu_G^*."""    mucrit = mu_G_star()    if abs(mu - mucrit) < tol:        return "border"    elif mu < mucrit:        return "good"    else:        return "bad"# ============================================================# THRESHOLDS# ============================================================mu_crit = mu_G_star()alpha_crit = alpha_critical_symmetric(kappa)print("=" * 60)print("BASELINE CALIBRATION")print("=" * 60)print(f"B            = {B}")print(f"K0           = {K0}")print(f"c            = {c}")print(f"d            = {d}")print(f"gamma        = {gamma}")print(f"epsbar       = {epsbar}")print(f"alpha        = {alpha_baseline}")print(f"beta         = {beta_baseline}")print(f"s_bar        = {s_bar:.4f}")print(f"kappa        = {kappa:.4f}")print(f"mu_G^*       = {mu_crit:.6f}")print(f"alpha^*      = {alpha_crit:.6f}   (under alpha = beta)")print("=" * 60)# ============================================================# FIGURE 5.1: PHASE PORTRAITS# ============================================================def plot_phase_portraits():    mu_values = [0.3, mu_crit, 0.9]    titles = [        r"(a) Low protection ($\mu=0.3$)",        r"(b) Threshold case ($\mu=\mu_G^*$)",        r"(c) High protection ($\mu=0.9$)"    ]    initial_conditions = [        (0.10, 0.10),        (0.10, 0.90),        (0.90, 0.10),        (0.90, 0.90),        (0.50, 0.50)    ]    traj_colors = ["#1f77b4", "#ff7f0e", "#2ca02c", "#9467bd", "#8c564b"]    fig, axes = plt.subplots(1, 3, figsize=(17, 5.4), sharey=True)    for ax, mu, title in zip(axes, mu_values, titles):        regime = classify_regime(mu)        s1 = s1_frontier(mu)        s0 = s0_frontier(mu)        # Regime shading        if s1 > 1.0:            ax.axvspan(0.0, 1.0, color="#c7e9c0", alpha=0.45, zorder=0)            ax.text(0.50, 0.05, r"Full-compliance region: $\pi=1$",                    ha="center", va="center", fontsize=9, color="0.30")        else:            ax.axvspan(0.0, min(s1, 1.0), color="#c7e9c0", alpha=0.45, zorder=0)            ax.axvspan(min(s1, 1.0), min(s0, 1.0), color="#fee8c8", alpha=0.50, zorder=0)            if s0 <= 1.0:                ax.axvspan(s0, 1.0, color="#fcbba1", alpha=0.45, zorder=0)            ax.axvline(s1, color="darkgreen", linestyle="--", linewidth=1.0)            ax.text(s1 + 0.015, 0.05, r"$s_1(\mu)$", fontsize=9, color="darkgreen")            if s0 <= 1.0:                ax.axvline(s0, color="darkred", linestyle=":", linewidth=1.0)                ax.text(s0 + 0.015, 0.11, r"$s_0(\mu)$", fontsize=9, color="darkred")        # Trajectories        for (s_init, p_init), col in zip(initial_conditions, traj_colors):            s_traj, p_traj = simulate(                s_init, p_init, mu,                alpha_baseline, beta_baseline, T=220            )            ax.plot(s_traj, p_traj, color=col, linewidth=1.1, alpha=0.9)            ax.plot(s_init, p_init, marker="o", color=col, markersize=4)            mid = 40            ax.annotate(                "",                xy=(s_traj[mid + 1], p_traj[mid + 1]),                xytext=(s_traj[mid], p_traj[mid]),                arrowprops=dict(arrowstyle="->", color=col, lw=1.0)            )        # Good equilibrium        if regime in ["good", "border"]:            ax.plot(s_bar, 1.0, marker="*", color="black", markersize=12, zorder=5)            ax.annotate(                r"$E_G$",                xy=(s_bar, 1.0),                xytext=(s_bar - 0.18, 0.90),                fontsize=11,                color="black",                arrowprops=dict(arrowstyle="->", lw=0.8, color="black")            )        # Internal equilibrium if admissible        s_fp, p_fp = fixed_point_internal(mu)        if (s1 < s_fp < min(s0, 1.0)) and (0.0 < p_fp < 1.0):            ax.plot(s_fp, p_fp, marker="s", color="black", markersize=7, zorder=5)            ax.annotate(                r"$E_I$",                xy=(s_fp, p_fp),                xytext=(s_fp + 0.10, p_fp + 0.10),                fontsize=11,                color="black",                arrowprops=dict(arrowstyle="->", lw=0.8, color="black")            )        ax.set_xlim(0.0, 1.0)        ax.set_ylim(0.0, 1.02)        ax.set_xlabel(r"Compliance standard, $s_t$")        ax.set_title(title)        ax.grid(True)    axes[0].set_ylabel(r"Expected compliance, $p_t$")    plt.tight_layout()    plt.savefig(os.path.join(OUTPUT_DIR, "phase_portraits.png"), bbox_inches="tight")    plt.show()# ============================================================# FIGURE 5.2: BIFURCATION DIAGRAM# ============================================================def plot_bifurcation():    mu = 0.9    a_vals = np.linspace(0.10, 0.99, 600)    T = 5000    T_trans = 4000    all_a = []    all_s = []    for a in a_vals:        s_traj, _ = simulate(0.5, 0.5, mu, a, a, T=T)        s_asym = s_traj[T_trans:]        all_a.extend([a] * len(s_asym))        all_s.extend(s_asym)    fig, ax = plt.subplots(figsize=(9.2, 5.4))    ax.scatter(all_a, all_s, s=0.10, color="#1f77b4", alpha=0.60, edgecolors="none")    ax.axvline(alpha_crit, linestyle="--", color="red", lw=1.4)    ax.text(alpha_crit + 0.01, 0.20, r"$\alpha^*=\beta^*$", fontsize=11, color="red")    ax.set_xlim(0.10, 1.00)    ax.set_xlabel(r"Symmetric adjustment speed, $\alpha=\beta$")    ax.set_ylabel(r"Asymptotic values of $s_t$")    ax.set_title(r"Bifurcation diagram for $\mu=0.9$")    ax.grid(False)    plt.tight_layout()    plt.savefig(os.path.join(OUTPUT_DIR, "bifurcation.png"), bbox_inches="tight")    plt.show()# ============================================================# POST-NEIMARK-SACKER: PERIOD DETECTION# ============================================================def detect_period(x, tol_amp=1e-6, tol_period=1e-6, max_period=30):    """    Detect periodicity in a time series x.    Returns:      1  -> fixed point      0  -> quasi-periodic / aperiodic      p>1 -> cycle of period p    """    amp = np.max(x) - np.min(x)    if amp < tol_amp:        return 1    for p in range(2, max_period + 1):        if len(x) >= 4 * p:            c1 = x[0:p]            c2 = x[p:2*p]            c3 = x[2*p:3*p]            c4 = x[3*p:4*p]            if (                np.max(np.abs(c1 - c2)) < tol_period and                np.max(np.abs(c2 - c3)) < tol_period and                np.max(np.abs(c3 - c4)) < tol_period            ):                return p    return 0def label_from_period(period):    """Convert detected period into a readable label."""    if period == 1:        return "Stable fixed point"    elif period == 0:        return "Quasi-periodic orbit"    else:        return f"Period-{period} cycle"def post_ns_classification():    mu_ns = 0.9    a_grid = np.linspace(0.10, 0.99, 500)    periods = []    amplitudes = []    for a in a_grid:        s_traj, p_traj = simulate(            0.50, 0.50, mu_ns,            alpha=a, beta=a,            T=8000        )        s_asym = s_traj[6000:]        amp = np.max(s_asym) - np.min(s_asym)        per = detect_period(s_asym, tol_amp=1e-6, tol_period=1e-6, max_period=30)        periods.append(per)        amplitudes.append(amp)    periods = np.array(periods)    amplitudes = np.array(amplitudes)    print("\n" + "=" * 60)    print("POST-NEIMARK-SACKER CLASSIFICATION")    print("=" * 60)    print(f"Critical threshold (alpha = beta): {alpha_crit:.6f}")    print(f"Stable fixed point values:         {np.sum(periods == 1)}")    print(f"Quasi-periodic values:             {np.sum(periods == 0)}")    print(f"Locked periodic values:            {np.sum(periods > 1)}")    locked = periods > 1    if np.any(locked):        unique_periods = np.unique(periods[locked])        print(f"Detected periods:                  {unique_periods}")        for pp in unique_periods:            vals = a_grid[periods == pp]            print(f"  Period {pp:2d}: alpha in [{vals[0]:.3f}, {vals[-1]:.3f}]")    return a_grid, periods, amplitudes# ============================================================# FIGURE 5.3: BIFURCATION DIAGRAM IN mu# ============================================================def plot_bifurcation_mu():    mu_vals        = np.linspace(0.01, 0.99, 600)    T_stable       = 4000   # sufficiente per alpha=0.5    T_unstable     = 12000  # lungo per alpha=0.85, specie per mu < mu_G*    T_trans_stable   = 3000    T_trans_unstable = 10000    alpha_stable   = 0.5    alpha_unstable = 0.85    mu_star        = mu_G_star()    def collect_asymptotic(alpha_val, T, T_trans):        all_mu, all_s = [], []        for mu in mu_vals:            s_traj, _ = simulate(0.5, 0.5, mu, alpha_val, alpha_val, T=T)            s_asym = s_traj[T_trans:]            # Per mu <= mu_G*, teniamo solo il valore finale            # (evita dispersione residua da transitorio)            if mu <= mu_star:                all_mu.append(mu)                all_s.append(s_asym[-1])            else:                all_mu.extend([mu] * len(s_asym))                all_s.extend(s_asym)        return np.array(all_mu), np.array(all_s)    mu_st, s_st   = collect_asymptotic(alpha_stable,   T_stable,   T_trans_stable)    mu_uns, s_uns = collect_asymptotic(alpha_unstable, T_unstable, T_trans_unstable)    # Curve analitiche    mu_good = np.linspace(0.01, mu_star, 200)    s_good  = np.full_like(mu_good, s_bar)    mu_bad  = np.linspace(mu_star, 0.99, 200)    s_bad   = np.array([fixed_point_internal(m)[0] for m in mu_bad])    fig, axes = plt.subplots(1, 2, figsize=(14, 5.2), sharey=True)    titles = [        r"(a) Stable regime: $\alpha=\beta=0.50 < \alpha^*$",        r"(b) Unstable regime: $\alpha=\beta=0.85 > \alpha^*$"    ]    data = [(mu_st, s_st), (mu_uns, s_uns)]    for ax, (mu_d, s_d), title in zip(axes, data, titles):        # Regime shading        ax.axvspan(0.0,    mu_star, color="#2ca02c", alpha=0.06)        ax.axvspan(mu_star, 1.0,   color="#d62728", alpha=0.06)        # Punti asintotici        # Per mu <= mu_G*: punti singoli, marker più visibile        mask_good = mu_d <= mu_star        mask_bad  = mu_d >  mu_star        ax.scatter(mu_d[mask_good], s_d[mask_good],                   s=4.0, color="#2ca02c", alpha=0.8,                   edgecolors="none", rasterized=True)        ax.scatter(mu_d[mask_bad], s_d[mask_bad],                   s=0.04, color="#1f77b4", alpha=0.35,                   edgecolors="none", rasterized=True)        # Curve analitiche        ax.plot(mu_good, s_good, color="#2ca02c", linewidth=1.8,                label=r"$E_G = \bar{s}$")        ax.plot(mu_bad, s_bad, color="black", linewidth=1.4,                linestyle="--", label=r"$s^*(\mu)$ — $E_I$")        # Soglia critica        ax.axvline(mu_star, color="red", linestyle="--", linewidth=1.2)        ax.text(mu_star + 0.01, 0.06, r"$\mu_G^*$",                fontsize=11, color="red")        ax.set_xlabel(r"Implicit protection, $\mu$")        ax.set_title(title)        ax.legend(loc="upper right", fontsize=9)        ax.set_xlim(0.0, 1.0)        ax.set_ylim(0.0, 1.0)        ax.grid(False)    axes[0].set_ylabel(r"Asymptotic values of $s_t$")    plt.tight_layout()    plt.savefig(os.path.join(OUTPUT_DIR, "bifurcation_mu.png"),                bbox_inches="tight", dpi=300)        plt.show()    print("Figure A saved.")# ============================================================# FIGURE 5.4: POST-NEIMARK-SACKER PHASE PORTRAITS# ============================================================def plot_post_ns_phase_portraits():    mu_ns = 0.9    s_fp, p_fp = fixed_point_internal(mu_ns)    s1 = s1_frontier(mu_ns)    selected_a = [0.82, 0.90, 0.97]    fig, axes = plt.subplots(1, 3, figsize=(17, 5.6), sharey=True)    for ax, a_val, panel in zip(axes, selected_a, ["(a)", "(b)", "(c)"]):        s_traj, p_traj = simulate(            0.50, 0.50, mu_ns,            alpha=a_val, beta=a_val,            T=8000        )        s_asym = s_traj[6000:]        detected = detect_period(s_asym, tol_amp=1e-6, tol_period=1e-6, max_period=30)        label = label_from_period(detected)        # Early transient        ax.plot(            s_traj[:500], p_traj[:500],            color="gray", linewidth=0.5, alpha=0.5        )        # Asymptotic orbit        ax.plot(            s_traj[6000:], p_traj[6000:],            ".",            color="#1f77b4",            markersize=0.50,            alpha=0.75        )        # Unstable fixed point        ax.plot(s_fp, p_fp, marker="+", color="red", markersize=12, mew=1.5)        ax.text(s_fp + 0.015, p_fp - 0.03, r"$E_I$", fontsize=10, color="red")        # Frontier        ax.axvline(s1, color="darkgreen", linestyle="--", linewidth=0.9)        ax.text(s1 + 0.01, 0.96, r"$s_1(\mu)$", fontsize=9, color="darkgreen")        ax.set_xlim(0.20, 0.90)        ax.set_ylim(0.25, 1.02)        ax.set_xlabel(r"$s_t$")        ax.set_title(f"{panel} {label}\n" + rf"$\alpha=\beta={a_val:.2f}$")        ax.grid(True)    axes[0].set_ylabel(r"$p_t$")    plt.tight_layout()    plt.savefig(os.path.join(OUTPUT_DIR, "post_ns_phase_portraits.png"), bbox_inches="tight")    plt.show()# ============================================================# FIGURE 5.5: REGIME MAP IN THE (mu, K0) PLANE# ============================================================def plot_regime_map_mu_K0():    N       = 500    mu_grid = np.linspace(0.01, 0.99, N)    K0_grid = np.linspace(0.5,  8.0,  N)    MU, KK  = np.meshgrid(mu_grid, K0_grid)    REGIME = np.zeros((N, N))    kappa_loc = gamma * c / (d * epsbar)    det_val   = jacobian_determinant(alpha_baseline, beta_baseline, kappa_loc)    for i in range(N):        for j in range(N):            mu_val = MU[i, j]            K0_val = KK[i, j]            mu_star_loc = 1.0 - (epsbar * s_bar + 0.5 * c * s_bar**2 - B) / K0_val            if mu_star_loc >= 1.0 or mu_val <= mu_star_loc:                REGIME[i, j] = 0  # GOOD            else:                if det_val < 1.0:                    REGIME[i, j] = 1  # BAD_STABLE                else:                    REGIME[i, j] = 2  # BAD_UNSTABLE    # Analytical frontier mu_G*(K0)    K0_line  = np.linspace(0.5, 8.0, 600)    mu_front = 1.0 - (epsbar * s_bar + 0.5 * c * s_bar**2 - B) / K0_line    mu_front = np.clip(mu_front, 0.0, 1.0)    # Solo due colori: good e bad stable    from matplotlib.colors import ListedColormap, BoundaryNorm    cmap   = ListedColormap(["#2ca02c", "#1f77b4"])    bounds = [-0.5, 0.5, 1.5]    norm   = BoundaryNorm(bounds, cmap.N)    fig, ax = plt.subplots(figsize=(8.5, 6.5))    im = ax.pcolormesh(MU, KK, REGIME, cmap=cmap, norm=norm,                       shading="auto", alpha=0.85, rasterized=True)    # Analytical frontier    ax.plot(mu_front, K0_line, color="black", linewidth=2.0,            label=r"$\mu_G^*(K_0)$ frontier")    # Baseline point    K0_base = 3.0    mu_base = 0.9    ax.plot(mu_base, K0_base, marker="o", color="white", markersize=8,            markeredgecolor="black", markeredgewidth=1.5,            zorder=5, label=r"Baseline $(\mu=0.9,\ K_0=3)$")    ax.text(mu_base - 0.18, K0_base + 0.15, r"Baseline",            fontsize=9, color="black", zorder=6)    ax.axhline(K0_base, color="gray", linestyle=":", linewidth=1.0, alpha=0.6)    ax.axvline(mu_G_star(), color="gray", linestyle=":", linewidth=1.0, alpha=0.6)    # Region labels — ben separati e non sovrapposti    ax.text(0.08, 7.0, "Good equilibrium",            fontsize=12, color="white", fontweight="bold")    ax.text(0.65, 1.5, "Bad stable",            fontsize=12, color="white", fontweight="bold")    # Colorbar — solo due voci    cbar = plt.colorbar(im, ax=ax, ticks=[0, 1], shrink=0.88)    cbar.ax.set_yticklabels(["Good eq.", "Bad stable"], fontsize=10)    ax.set_xlabel(r"Implicit protection, $\mu$", fontsize=12)    ax.set_ylabel(r"Punishment severity, $K_0$", fontsize=12)    ax.set_title(r"Regime map in the $(\mu,\, K_0)$ plane", fontsize=12)    ax.set_xlim(0.0, 1.0)    ax.set_ylim(0.5, 8.0)    ax.legend(loc="upper left", fontsize=9)    ax.grid(True, alpha=0.15)    plt.tight_layout()    plt.savefig(os.path.join(OUTPUT_DIR, "regime_map_mu_K0.png"),                bbox_inches="tight", dpi=300)    plt.show()    print("Figure B saved.")plot_regime_map_mu_K0()# ============================================================# FIGURE 5.6: STABILITY MAP IN THE (alpha, beta) PLANE# ============================================================def plot_stability_asymmetric():    N  = 500    a  = np.linspace(0.01, 0.99, N)    b  = np.linspace(0.01, 0.99, N)    AA, BB = np.meshgrid(a, b)    DET = jacobian_determinant(AA, BB, kappa)    # Analytical frontier alpha*(beta)    beta_range  = np.linspace(1.0/(2.0 + kappa) + 1e-3, 0.99, 600)    alpha_front = beta_range / (beta_range * (2.0 + kappa) - 1.0)    mask        = (alpha_front > 0.0) & (alpha_front < 1.0)    beta_range  = beta_range[mask]    alpha_front = alpha_front[mask]    # Symmetric critical point    alpha_sym = alpha_critical_symmetric(kappa)    # Diagonal    diag = np.linspace(0.01, 0.99, 200)    fig, axes = plt.subplots(1, 2, figsize=(14, 6.0))    # --------------------------------------------------------    # Panel (a): heatmap det(J*) — scala lineare, solo valori > 0    # --------------------------------------------------------    det_min = max(DET.min(), 0.0)    det_max = DET.max()    levels  = np.linspace(det_min, det_max, 50)    im = axes[0].contourf(AA, BB, DET, levels=levels,                          cmap="RdYlGn_r", alpha=0.90)    axes[0].contour(AA, BB, DET, levels=[1.0],                    colors="black", linewidths=1.8)    axes[0].plot(alpha_front, beta_range, "k--", lw=1.4,                 label=r"$\det(J^*)=1$ frontier")    axes[0].plot(diag, diag, color="gray", lw=1.0, linestyle=":",                 label=r"$\alpha=\beta$")    axes[0].plot(alpha_sym, alpha_sym, marker="D", color="black",                 markersize=6, zorder=5)    axes[0].text(alpha_sym + 0.02, alpha_sym - 0.06,                 r"$\alpha^*=\beta^*$", fontsize=9)    axes[0].plot(alpha_baseline, beta_baseline, "ko", ms=6, zorder=6)    axes[0].text(alpha_baseline + 0.02, beta_baseline - 0.06,                 "Baseline", fontsize=9)    axes[0].text(0.10, 0.18, "Stable region",                 fontsize=11, color="darkgreen", fontweight="bold")    axes[0].text(0.60, 0.82, "Unstable region",                 fontsize=11, color="darkred", fontweight="bold")    cbar = plt.colorbar(im, ax=axes[0], shrink=0.88)    cbar.set_label(r"$\det(J^*)$", fontsize=10)    axes[0].set_xlabel(r"Adjustment speed of standards, $\alpha$", fontsize=11)    axes[0].set_ylabel(r"Adjustment speed of beliefs, $\beta$", fontsize=11)    axes[0].set_title(r"(a) $\det(J^*)$ in the $(\alpha,\beta)$ plane",                      fontsize=11)    axes[0].legend(loc="upper left", fontsize=9)    axes[0].set_xlim(0.0, 1.0)    axes[0].set_ylim(0.0, 1.0)    axes[0].grid(True, alpha=0.15)    # --------------------------------------------------------    # Panel (b): asimmetrie — versione pulita    # --------------------------------------------------------    axes[1].contourf(AA, BB, DET, levels=[det_min, 1.0],                     colors=["#2ca02c"], alpha=0.25)    axes[1].contourf(AA, BB, DET, levels=[1.0, det_max],                     colors=["#d62728"], alpha=0.25)    axes[1].contour(AA, BB, DET, levels=[1.0],                    colors="black", linewidths=1.8)    axes[1].plot(alpha_front, beta_range, "k--", lw=1.4,                 label=r"$\det(J^*)=1$ frontier")    axes[1].plot(diag, diag, color="gray", lw=1.0, linestyle=":",                 label=r"$\alpha=\beta$ (symmetric)")    axes[1].plot(alpha_sym, alpha_sym, marker="D", color="black",                 markersize=6, zorder=5)    axes[1].text(alpha_sym + 0.02, alpha_sym - 0.06,                 r"$\alpha^*=\beta^*$", fontsize=9)    axes[1].plot(alpha_baseline, beta_baseline, "ko", ms=6, zorder=6)    axes[1].text(alpha_baseline + 0.02, beta_baseline - 0.06,                 "Baseline", fontsize=9)    # Quattro punti asimmetrici ben posizionati e verificati    # Sostituisci le coordinate dei punti instabili con queste    asymmetric_pts = [    (0.55, 0.95, r"$\alpha \ll \beta$  (unstable)"),    (0.95, 0.55, r"$\alpha \gg \beta$  (unstable)"),    (0.15, 0.40, r"$\alpha < \beta$  (stable)"),    (0.40, 0.15, r"$\alpha > \beta$  (stable)"),]        for (a_pt, b_pt, lbl) in asymmetric_pts:        det_pt = jacobian_determinant(a_pt, b_pt, kappa)        stable = det_pt < 1.0        col    = "#2ca02c" if stable else "#d62728"        marker = "s" if stable else "x"        axes[1].plot(a_pt, b_pt, marker=marker, color=col,                     markersize=9, mew=2.0, zorder=5)        # Offset label per evitare sovrapposizioni        x_off = 0.03        y_off = 0.03 if b_pt < 0.5 else -0.07        axes[1].text(a_pt + x_off, b_pt + y_off, lbl,                     fontsize=8.5, color=col)    # Labels regioni    axes[1].text(0.10, 0.18, "Stable region",                 fontsize=11, color="darkgreen", fontweight="bold")    axes[1].text(0.58, 0.82, "Unstable region",                 fontsize=11, color="darkred", fontweight="bold")    axes[1].set_xlabel(r"Adjustment speed of standards, $\alpha$",                       fontsize=11)    axes[1].set_ylabel(r"Adjustment speed of beliefs, $\beta$",                       fontsize=11)    axes[1].set_title(r"(b) Asymmetric adjustment speeds", fontsize=11)    axes[1].legend(loc="upper left", fontsize=9)    axes[1].set_xlim(0.0, 1.0)    axes[1].set_ylim(0.0, 1.0)    axes[1].grid(True, alpha=0.15)    plt.tight_layout()    plt.savefig(os.path.join(OUTPUT_DIR, "stability_map_asymmetric.png"),                bbox_inches="tight", dpi=300)    plt.show()    print("Figure C saved.")plot_stability_asymmetric()# ============================================================# RUN ALL# ============================================================plot_phase_portraits()plot_bifurcation()post_ns_classification()plot_post_ns_phase_portraits()plot_bifurcation_mu()plot_regime_map_mu_K0()plot_stability_asymmetric()# ============================================================# Figure 5.6: Counterfactual experiment# ============================================================def simulate_time_varying_mu(mu_series, s0=0.8, p0=1.0):    """    Simulate the model with time-varying mu_t.    Parameters    ----------    mu_series : array-like        Sequence of mu_t values.    s0, p0 : float        Initial conditions.    Returns    -------    s_path, p_path : np.ndarray    """    T = len(mu_series)    s_path = np.zeros(T)    p_path = np.zeros(T)    s_path[0] = s0    p_path[0] = p0    for t in range(T - 1):        pi_t = pi_func(s_path[t], mu_series[t])        br_t = best_reply_core(p_path[t])        s_path[t+1] = (1 - alpha_baseline) * s_path[t] + alpha_baseline * br_t        p_path[t+1] = (1 - beta_baseline) * p_path[t] + beta_baseline * pi_t    return s_path, p_pathdef run_counterfactual_experiment():    """    Historical vs counterfactual experiment:    - Historical: mu_t from data    - Counterfactual: constant low mu    """    # --- Load mu_t series ---    df = pd.read_csv("mu_series.csv")    years = df['year'].values    mu_hist = df['mu_t'].values    T = len(years)    # --- Scenario 1: Historical ---    s_hist, p_hist = simulate_time_varying_mu(mu_hist)    # --- Scenario 2: Counterfactual (low mu) ---    mu_low = 0.3    mu_cf_series = np.full(T, mu_low)    s_cf, p_cf = simulate_time_varying_mu(mu_cf_series)    # --- Threshold ---    mu_star = mu_G_star()    # ============================================================    # FIGURE    # ============================================================    fig, axes = plt.subplots(1, 3, figsize=(16, 5))    # Panel 1: mu_t    axes[0].plot(years, mu_hist, color="black", linewidth=1.8)    axes[0].axhline(mu_star, color="red", linestyle="--", linewidth=1.2,                    label=r"$\mu_G^*$")    axes[0].fill_between(        years, mu_star, mu_hist,        where=(mu_hist > mu_star),        color="red", alpha=0.15    )    axes[0].set_xlabel("Year")    axes[0].set_ylabel(r"$\mu_t$")    axes[0].set_title("Implicit Protection (Data-Based)")    axes[0].legend()    axes[0].grid(True)    # Panel 2: s_t    axes[1].plot(years, s_hist, color="#1f77b4", linewidth=1.8,                 label="Historical")    axes[1].plot(years, s_cf, color="#2ca02c", linestyle="--", linewidth=1.8,                 label="Counterfactual")    axes[1].fill_between(        years, s_hist, s_cf,        color="red", alpha=0.12,        label="Discipline gap"    )    axes[1].set_xlabel("Year")    axes[1].set_ylabel(r"$s_t$")    axes[1].set_title("Compliance Standard")    axes[1].legend()    axes[1].grid(True)    # Panel 3: p_t    axes[2].plot(years, p_hist, color="#1f77b4", linewidth=1.8,                 label="Historical")    axes[2].plot(years, p_cf, color="#2ca02c", linestyle="--", linewidth=1.8,                 label="Counterfactual")    axes[2].fill_between(        years, p_hist, p_cf,        color="red", alpha=0.12,        label="Compliance gap"    )    axes[2].set_xlabel("Year")    axes[2].set_ylabel(r"$p_t$")    axes[2].set_title("Expected Compliance")    axes[2].legend()    axes[2].grid(True)    plt.tight_layout()    plt.savefig(        os.path.join(OUTPUT_DIR, "counterfactual_experiment.png"),        bbox_inches="tight"    )    plt.show()    # ============================================================    # PRINT SUMMARY    # ============================================================    print("\n" + "="*70)    print("COUNTERFACTUAL SUMMARY")    print("="*70)    print(f"Average mu (historical): {np.mean(mu_hist):.3f}")    print(f"mu_G*: {mu_star:.3f}")    print("\nFinal values:")    print(f"Historical:     s = {s_hist[-1]:.3f}, p = {p_hist[-1]:.3f}")    print(f"Counterfactual: s = {s_cf[-1]:.3f}, p = {p_cf[-1]:.3f}")    print("\nAverage gaps:")    print(f"Mean s gap: {np.mean(s_cf - s_hist):.3f}")    print(f"Mean p gap: {np.mean(p_cf - p_hist):.3f}")    print("="*70)# ============================================================# RUN# ============================================================if __name__ == "__main__":    run_counterfactual_experiment()                    